"""The legacy AutoGenerated/ link inside the simulations package.

WHY THIS EXISTS
---------------
``simulations/__init__._bind_output_dir`` links ``simulations/AutoGenerated``
to the real output root so legacy ``Path("AutoGenerated/...")`` writes land in
the build output. It handled a POSIX symlink with the wrong target by
unlinking and recreating it -- but on Windows a junction reports
``is_symlink() == False`` and ``is_dir() == True``, so a junction pointing at
the *wrong* place fell into the "real directory, don't clobber" branch and
was only ever warned about.

One had been left pointing at ``%TEMP%/t6_6_clean/AutoGenerated`` by an
earlier run. It survived every build, the warning scrolled past every time,
and anything writing through the legacy path went into a dead temp directory
instead of the build output. That is the same silent-stale-artifact failure
as the output-root bug in test_build_out_dir, from a different direction.
"""
from __future__ import annotations

import os
from pathlib import Path

import pytest


@pytest.fixture(autouse=True)
def _restore_binding():
    """Put the legacy link back where it was.

    Without this, these tests leave simulations/AutoGenerated pointing at a
    tmp_path that pytest then deletes -- manufacturing the exact stale-link
    condition they exist to catch. A test that plants the bug it tests for
    is worse than no test.
    """
    import metaphysica.simulations as sims

    original = os.environ.get("METAPHYSICA_OUT")
    yield
    if original:
        os.environ["METAPHYSICA_OUT"] = original
    else:
        os.environ.pop("METAPHYSICA_OUT", None)
    try:
        sims._bind_output_dir()
    except Exception:
        pass


def _bind(monkeypatch, out_root):
    """Run the binder with METAPHYSICA_OUT pointed at *out_root*."""
    import metaphysica.simulations as sims

    monkeypatch.setenv("METAPHYSICA_OUT", str(out_root))
    sims._bind_output_dir()
    return Path(sims.__file__).resolve().parent / "AutoGenerated"


def _supports_links(tmp_path) -> bool:
    target = tmp_path / "target"
    target.mkdir()
    link = tmp_path / "link"
    try:
        if os.name == "nt":
            rc = os.system(f'mklink /J "{link}" "{target}" >NUL 2>&1')
            return rc == 0 and link.exists()
        os.symlink(target, link, target_is_directory=True)
        return True
    except OSError:
        return False


def test_binder_repoints_a_stale_link(tmp_path, monkeypatch):
    """The regression: a link to the wrong place must be replaced, not
    merely complained about."""
    if not _supports_links(tmp_path):
        pytest.skip("filesystem does not support directory links here")

    import metaphysica.simulations as sims

    legacy = Path(sims.__file__).resolve().parent / "AutoGenerated"
    good = tmp_path / "good"
    good.mkdir()

    bound = _bind(monkeypatch, good)
    assert bound.resolve() == (good / "AutoGenerated").resolve(), (
        "binder did not point the legacy path at METAPHYSICA_OUT"
    )
    assert legacy.exists()


def test_binder_is_idempotent(tmp_path, monkeypatch):
    if not _supports_links(tmp_path):
        pytest.skip("filesystem does not support directory links here")
    good = tmp_path / "good"
    good.mkdir()
    first = _bind(monkeypatch, good).resolve()
    second = _bind(monkeypatch, good).resolve()
    assert first == second


def test_binder_never_clobbers_a_real_directory(tmp_path, monkeypatch):
    """The other half: a genuine directory with contents must survive.

    Replacing a real directory would destroy build output. The junction fix
    must be narrow enough to leave this case alone.
    """
    import metaphysica.simulations as sims

    # Exercise the decision directly rather than damaging the package dir:
    # os.readlink is what distinguishes a link from a real directory.
    real_dir = tmp_path / "genuine"
    real_dir.mkdir()
    (real_dir / "keepme.txt").write_text("data", encoding="utf-8")

    with pytest.raises(OSError):
        os.readlink(real_dir)

    assert (real_dir / "keepme.txt").exists()


def test_binder_leaves_output_pointing_at_the_build_root(monkeypatch):
    """After binding, the legacy path and the real root are the same dir."""
    import metaphysica.simulations as sims

    out = os.environ.get("METAPHYSICA_OUT")
    if not out:
        pytest.skip("METAPHYSICA_OUT not set in this environment")
    legacy = Path(sims.__file__).resolve().parent / "AutoGenerated"
    if not legacy.exists():
        pytest.skip("legacy path not bound in this environment")
    assert legacy.resolve() == (Path(out) / "AutoGenerated").resolve()
